import {validateSnapshot} from './snapshot.js';
// Deliberately a separate database, with one replaceable record and no campaign writer.
function open(){return new Promise((resolve,reject)=>{const r=indexedDB.open('scroll-trainer-viewer',1);r.onupgradeneeded=()=>r.result.createObjectStore('snapshot');r.onerror=()=>reject(Error('Snapshot storage unavailable.'));r.onsuccess=()=>resolve(r.result);});}
export async function loadSnapshot(){const db=await open();try{return await new Promise((resolve,reject)=>{const t=db.transaction('snapshot','readonly'),r=t.objectStore('snapshot').get('current');r.onsuccess=()=>resolve(r.result?validateSnapshot(r.result):null);r.onerror=()=>reject(r.error);});}finally{db.close();}}
export async function replaceSnapshot(p){validateSnapshot(p);const db=await open();try{await new Promise((resolve,reject)=>{const t=db.transaction('snapshot','readwrite');t.objectStore('snapshot').put(p,'current');t.oncomplete=resolve;t.onabort=()=>reject(Error('Snapshot was not saved. Previous snapshot is unchanged.'));});}finally{db.close();}}
